import importlib.util
s='[O][C][C][N][C][C][Ring1][Ring2][Branch1][C][O][C][Ring1][=Branch1][O]'
print('SELFIES installed:', importlib.util.find_spec('selfies') is not None)
print('RDKit installed:', importlib.util.find_spec('rdkit') is not None)
if importlib.util.find_spec('selfies'):
 import selfies
 try:
  smi=selfies.decoder(s)
  print('decoded_smiles:', smi)
 except Exception as e: print('selfies_error:', type(e).__name__, str(e))
if importlib.util.find_spec('rdkit'):
 from rdkit import Chem
 for label, x in [('input',s)]:
  m=Chem.MolFromSmiles(x)
  print(label, 'rdkit_smiles:', Chem.MolToSmiles(m) if m else None)
  if m: print('formula_atoms:', [(a.GetSymbol(),a.GetIsAromatic()) for a in m.GetAtoms()])
